<?= $this->extend('layout') ?><?= $this->section('content') ?><section class="card"><h1>Add Staff Member</h1><form method="post" enctype="multipart/form-data" action="<?= site_url('users') ?>"><?= csrf_field() ?><label for="username">Username</label><input id="username" name="username" minlength="3" maxlength="50" pattern="[A-Za-z0-9]+" required value="<?= esc(old('username')) ?>"><label for="full_name">Full name</label><input id="full_name" name="full_name" maxlength="100" required value="<?= esc(old('full_name')) ?>"><label for="password">Initial password</label><input id="password" type="password" name="password" minlength="10" maxlength="255" required><small>Use at least 10 characters.</small><label for="avatar">Avatar</label><input id="avatar" type="file" name="avatar" accept="image/jpeg,image/png"><small>Optional JPG or PNG image, maximum 2 MB. It will be resized for display.</small><p><button>Save Staff Member</button> <a href="<?= site_url('users') ?>">Cancel</a></p></form></section><?= $this->endSection() ?>
